import * as C from './core.js';
import * as Store from './storage.js';
import {readWorkbook,applyLegacy,exportWorkbook} from './excel.js';
import {SyncEngine,createLink,prepareLocalChange} from './sync-engine.js';
import {stripSyncSecrets} from './sync-model.js';
import {createSyncUI} from './sync-ui.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
let state,year=2027,month='2027-01',view='home',busy=false,hidden=false,search='',pendingImport=null,swRegistration=null;
let syncConflicts=[];
const sync=new SyncEngine({getState:()=>state,persist:(fn,opts={})=>{if(opts.noChange)return;if((busy||modal.open)&&!opts.allowDialog)throw Object.assign(Error('当前编辑完成后继续同步'),{retry:true});return commit(fn,null,{internal:true,...opts});},canApply:()=>!busy&&!modal.open,isVisible:()=>!document.hidden,onStatus:paintSyncStatus,onConflict:items=>{syncConflicts=items;}});
const titles={home:['家庭概览','把生活过好，也把积累看清。'],ledger:['收支记录','随手记下，每一笔都心中有数。'],assets:['资产与负债','用同一天的余额，看见真实的变化。'],budget:['年度计划','为今天留余地，为明天做准备。'],travel:['旅行基金','把期待，安排进生活。'],review:['月度复盘','每个月，留一点时间给家庭。'],settings:['数据与设置','你的家庭数据，由你掌握。']};
const paths={home:'M3 10.5 12 3l9 7.5M5 9v11h5v-6h4v6h5V9',ledger:'M6 3h12v18l-3-2-3 2-3-2-3 2V3Zm3 5h6m-6 4h6',assets:'M4 20V10h4v10m4 0V4h4v16m4 0V8h2v12M2 21h21',budget:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16m-12 4h3m3 0h2m-8 3h3',travel:'m3 10 7 2 4 9 2-1-1-8 6-6c2-2 0-4-2-2l-6 6-8-1Z',review:'M8 4H5v17h14V4h-3M8 3h8v4H8zM8 13l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-7-4 3-1 2 2h4l2-2 3 2v3l2 2v4l-2 2v3l-3 2-2-2h-4l-2 2-3-2v-3l-2-2v-4l2-2Z',plus:'M12 5v14M5 12h14',arrow:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',close:'m6 6 12 12M6 18 18 6',wallet:'M3 6h18v15H3zM3 6l14-3v3m-2 6h6v5h-6z',flag:'M5 22V3m0 0c5-4 9 5 15 0v10c-6 5-10-4-15 0',circle:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z',refresh:'M20 8A8 8 0 1 0 20 17m0-14v5h-5'};
const icon=(id,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.circle}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amount=(v,symbol=true)=>hidden?'••••':`${v===null||v===undefined?'':symbol?'¥ ':''}${C.money(v)}`;
const pill=(text,tone='')=>`<span class="pill ${tone}">${text}</span>`;
const btn=(label,act,style='secondary',ico='',data='')=>`<button class="button ${style}" data-act="${act}" ${data}>${ico?icon(ico,17):''}${label}</button>`;
const empty=(title,text,action='')=>`<div class="empty"><span class="empty-icon">${icon('ledger',27)}</span><h3>${title}</h3><p>${text}</p>${action}</div>`;
const progress=(value,target,tone='blue')=>`<div class="progress ${tone}" role="progressbar" aria-label="目标完成比例" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.max(0,Math.min(100,Math.round((value||0)/target*100)||0))}"><i style="width:${Math.max(0,Math.min(100,(value||0)/target*100)||0)}%"></i></div>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;
const moneyField=(label,name,value='',optional=false,negative=false)=>field(label,name,value,'number',`step="0.01" ${negative?'':'min="0"'} max="1000000000000" ${optional?'placeholder="未知，留空"':'required'} inputmode="decimal"`);
const yearOptions=()=>[...new Set([2026,2027,...Object.keys(state.budgets).map(Number),...state.transactions.map(t=>+t.date.slice(0,4)),year])].sort().map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('');
const syncUI=createSyncUI({getState:()=>state,getConflicts:()=>syncConflicts,engine:sync,showDialog,commit,esc,btn,field});
const syncPanel=()=>syncUI.panel(),syncConnectDialog=()=>syncUI.connect(),syncPairDialog=()=>syncUI.pair(),syncConflictDialog=()=>syncUI.conflict();
function notify(text,error=false){const t=$('#toast');t.textContent=text;t.className=error?'visible error':'visible';clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.className='',4500);}
function setTheme(){document.documentElement.dataset.theme=state?.preferences.theme||'system';}
function showDialog(title,body,submitLabel='保存',onSubmit,wide=false){modal.innerHTML=`<form id="dialogForm"><header class="dialog-head"><h2>${title}</h2><button type="button" class="icon-button" data-act="close" aria-label="关闭">${icon('close')}</button></header><div class="dialog-body ${wide?'wide':''}">${body}</div><p id="dialogError" class="form-error" role="alert"></p><footer class="dialog-foot">${btn('取消','close','secondary')}<button type="submit" class="button primary">${submitLabel}</button></footer></form>`;modal.classList.toggle('wide-dialog',wide);modal.showModal();$('#dialogForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const button=e.submitter;button.disabled=true;try{await onSubmit(new FormData(e.currentTarget));if(modal.open)modal.close();}catch(err){$('#dialogError').textContent=err.message;button.disabled=false;}};}
async function commit(mutator,message,options={}){if(options.noChange)return;if(busy)throw Error('正在保存，请稍候。');if(!state)throw Error('请先解锁工作台。');busy=true;try{const candidate=structuredClone(state);await mutator(candidate);if(!options.internal&&!options.disconnect){try{prepareLocalChange(state,candidate);}catch(e){if(candidate.syncLink)candidate.syncLink.syncError=e.message;}}const saved=await Store.saveState(candidate);state=saved;render();if(!options.internal)sync.changed();if(message)notify(message);}finally{busy=false;}}
function paintSyncStatus(status){document.querySelectorAll('[data-sync-status]').forEach(el=>{el.textContent=status.text;el.dataset.kind=status.kind;});}

function navigate(v){view=v;search='';location.hash=v;render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function render(){if(!state)return;setTheme();const [title,sub]=titles[view]||titles.home;const nav=Object.entries(titles).map(([id,[name]])=>`<button class="nav-item ${view===id?'active':''}" data-act="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span>${id==='review'?'<i class="nav-dot"></i>':''}</button>`).join('');
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#home" data-act="nav" data-view="home"><span class="appmark">${icon('home',25)}</span><div>家庭工作台<small>FAMILY HUB</small></div></a><div class="space-label">我的家庭空间</div><nav aria-label="主要导航">${nav}</nav><div class="sidebar-foot"><div class="local-indicator"><i></i> 本机私密空间</div><p>让每一份积累，都有迹可循。</p><button class="profile" data-act="nav" data-view="settings"><span class="avatar">家</span><span>我们的家庭<small>财务工作台 · v1.2</small></span>${icon('settings',16)}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs">我的家庭 <span>/</span> ${title}</div><div class="top-actions"><span class="connection"><i class="${navigator.onLine?'':'offline'}"></i>${navigator.onLine?'本机已就绪':'离线可记录'}</span><button class="icon-button" data-act="hide" aria-label="${hidden?'显示':'隐藏'}金额" title="${hidden?'显示':'隐藏'}金额">${icon('eye')}</button><button class="icon-button" data-act="theme" aria-label="切换明暗模式">${icon('moon')}</button>${Store.isEncrypted()?`<button class="icon-button" data-act="lock" aria-label="锁定工作台">${icon('lock')}</button>`:''}<span class="avatar small">家</span></div></header><main id="main" tabindex="-1"><div class="page-heading"><div><p class="eyebrow">${view==='home'?'A LITTLE MORE PEACE OF MIND':'FAMILY HUB / '+view.toUpperCase()}</p><h1>${title}<span class="heading-dot">.</span></h1><p class="subtitle">${sub}</p></div><div class="heading-actions"><label class="year-select"><span class="sr-only">记录年份</span>${icon('budget',16)}<select id="yearSelect" aria-label="记录年份">${yearOptions()}</select></label>${btn('记一笔','add-tx','primary','plus')}</div></div>${state.syncLink?`<div class="sync-strip"><span data-sync-status>${esc(sync.status.text)}</span>${btn('同步设置','nav','text','','data-view="settings"')}</div>`:''}${({home:homeView,ledger:ledgerView,assets:assetsView,budget:budgetView,travel:travelView,review:reviewView,settings:settingsView}[view]||homeView)()}<footer class="page-footer"><span>${icon(Store.isEncrypted()?'lock':'check',13)} ${Store.isEncrypted()?'数据已在本机加密':'数据仅保存在此浏览器'}${state.updatedAt?' · '+new Date(state.updatedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):''}</span><button data-act="nav" data-view="settings">备份与隐私 ${icon('arrow',12)}</button></footer></main><nav class="mobile-nav" aria-label="手机导航">${[['home','概览'],['ledger','收支'],['assets','资产'],['review','复盘'],['settings','更多']].map(([id,label])=>`<button data-act="nav" data-view="${id}" class="${view===id?'active':''}">${icon(id,21)}<span>${label}</span></button>`).join('')}</nav></div>`;
 paintSyncStatus(sync.status);
 $('#yearSelect').onchange=e=>{year=+e.target.value;month=`${year}-${month.slice(5)}`;render();};
 $('#monthSelect')?.addEventListener('change',e=>{month=e.target.value;render();});
 $('#search')?.addEventListener('input',e=>{search=e.target.value;renderTransactions();});
}
function latestSnapshot(){return state.snapshots.filter(s=>s.date<=C.chinaToday()).sort((a,b)=>b.date.localeCompare(a.date))[0]||null;}
function metric(title,value,desc,ico,tone=''){return `<article class="card metric"><div class="metric-top"><span>${title}</span><span class="metric-icon ${tone}">${icon(ico)}</span></div><strong class="metric-value">${amount(value)}</strong><p>${desc}</p></article>`;}
function homeView(){const b=C.budgetFor(state,year),a=C.annualInfo(state,year),s=latestSnapshot(),si=C.snapshotInfo(s),r=C.nextReview(),first=!state.transactions.length&&!state.snapshots.length&&!Object.keys(state.months).length;
 return `${first?`<section class="welcome"><div class="welcome-symbol">${icon('home',24)}</div><div><h3>欢迎回家，从一份真实的记录开始</h3><p>家庭金额仅保存在加密空间。首次使用请导入自己的 Excel 或初始化文件，再按账单记录。</p></div>${btn('导入已有表格','import','light','upload')}</section>`:''}<div class="stats-grid">${metric('已核实金融资产',si.financial,s?.verified?`截至 ${s.date} · 不含房产`:'等待录入并核实首份资产快照','assets','blue')}${metric('可用现金储备',si.reserve,`扣除已有用途 · 目标 ${amount(b.reserve)}`,'wallet','green')}${metric(`${year} 年工资结余`,a.salarySaving,`${a.count} 个月已核对 · 年度目标 ${amount(b.annual)}`,'flag','purple')}</div><div class="dashboard-grid"><section class="card chart-card"><div class="card-heading"><div><h2>每一份积累，都向前一点</h2><p>工资累计结余与年度目标</p></div><span class="legend"><i></i>已核对结余 <i class="target"></i>目标</span></div>${savingsChart(a,b)}<div class="chart-bottom"><span>${a.count?'仅纳入已完成核对的月份':'等待第一份月度复盘，实际曲线将在这里出现'}</span>${btn('查看年度计划','nav','text','arrow','data-view="budget"')}</div></section><section class="card savings-card"><div class="card-heading"><div><h2>今年，留给未来</h2><p>工资储蓄目标</p></div>${icon('flag',22)}</div><div class="ring" style="--p:${Math.max(0,Math.min(100,(a.salarySaving||0)/b.annual*100))||0}%"><div><strong>${a.salarySaving===null?'待开始':(b.annual?Math.round(a.salarySaving/b.annual*100)+'%':'未设目标')}</strong><span>${a.count} / 12 个月已核对</span></div></div><div class="target-pair"><span>固定每月<strong>${amount(b.fixed)}</strong></span><span>争取每月<strong>${amount(b.stretch)}</strong></span></div><p class="muted tiny">已核对综合结余 ${amount(a.saving)}<br>综合积累争取 ${amount(b.combined)} / 年<br>奖金及当年新增股权，按实际净到账计入。</p></section><section class="card"><div class="card-heading"><div><h2>资产，先看清再计划</h2><p>现金与证券按同日快照记录</p></div>${btn('管理','nav','text','arrow','data-view="assets"')}</div><div class="asset-row"><span class="asset-icon blue">${icon('wallet')}</span><div>现金及存款<small>${s?.verified?'账单已核实':'尚无已核实余额'}</small></div><strong>${amount(s?.verified?s.cash:null)}</strong></div><div class="asset-row"><span class="asset-icon purple">${icon('assets')}</span><div>美股账户净权益<small>已扣融资，账户现金不重复计入</small></div><strong>${amount(s?.verified&&s.netConfirmed?s.usNet:null)}</strong></div><div class="asset-row"><span class="asset-icon teal">${icon('assets')}</span><div>其他投资净值<small>独立账户，避免与美股重复</small></div><strong>${amount(s?.verified?s.otherNet:null)}</strong></div><div class="reference-note">${privateReferences()}</div></section><section class="card review-preview"><div class="card-heading"><div><h2>给家庭的一点时间</h2><p>每月 5 日，一起回看上个月</p></div><span class="calendar-badge">5<small>每月</small></span></div><div class="reminder-date">${r.date.slice(5).replace('-',' 月 ')} 日 <span>20:00</span></div><p class="muted">北京时间 · 复盘 ${r.month.replace('-',' 年 ')} 月</p><div class="checklist"><span>${icon('circle',16)} 核对收支与储蓄进度</span><span>${icon('circle',16)} 更新月末资产与融资余额</span><span>${icon('circle',16)} 留下一条下月行动</span></div>${btn('开始月度复盘','review-month','secondary','arrow',`data-month="${r.month}"`)}<p class="tiny muted">独立提醒已设置。此处展示计划，不重复创建提醒。</p></section></div><section class="card todo-card"><div class="card-heading"><div><h2>家庭待办</h2><p>让重要的小事，有个着落</p></div>${btn('添加待办','add-todo','text','plus')}</div>${todoList()}</section>`;
}
function savingsChart(a,b){const w=640,h=215,left=42,top=15,bottom=175,width=570;let cum=0;const values=a.months.map(m=>{if(!m.reviewed)return null;cum+=m.salarySaving;return cum;}),max=Math.max(b.annual,...values.filter(v=>v!==null),1),min=Math.min(0,...values.filter(v=>v!==null)),y=v=>top+(max-v)/(max-min||1)*(bottom-top),x=i=>left+i*width/11;const target=Array.from({length:12},(_,i)=>`${i?'L':'M'}${x(i)},${y(b.annual*(i+1)/12)}`).join(' ');let path='',active=false;values.forEach((v,i)=>{if(v===null){active=false;return;}path+=`${active?'L':'M'}${x(i)},${y(v)} `;active=true;});return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${a.count?`${a.count} 个月已核对，工资结余 ${C.money(a.salarySaving)} 元`:'暂无已核对收支，仅显示目标参考线'}">${[0,.5,1].map(f=>{const v=min+(max-min)*f;return `<path d="M${left} ${y(v)}H${left+width}" stroke="var(--line)" stroke-dasharray="3 5"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${hidden?'••':(v/10000).toFixed(v%10000?1:0)+'万'}</text>`;}).join('')}<path d="${target}" fill="none" stroke="var(--blue)" stroke-opacity=".3" stroke-width="2" stroke-dasharray="5 6"/>${path?`<path d="${path}" fill="none" stroke="var(--blue)" stroke-width="3"/>`:''}${values.map((v,i)=>v===null?'':`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="var(--blue)"><title>${i+1} 月：${hidden?'已隐藏':C.money(v)+' 元'}</title></circle>`).join('')}${Array.from({length:12},(_,i)=>`<text x="${x(i)}" y="200" text-anchor="middle">${i+1}月</text>`).join('')}${!a.count?'<text x="330" y="108" class="chart-empty" text-anchor="middle">记录生活，积累会慢慢显现</text>':''}</svg></div>`;}
function monthPicker(){return `<label class="month-picker">${icon('budget',17)}<select id="monthSelect" aria-label="记录月份">${Array.from({length:12},(_,i)=>{const v=`${year}-${String(i+1).padStart(2,'0')}`;return `<option value="${v}" ${month===v?'selected':''}>${year} 年 ${i+1} 月</option>`;}).join('')}</select></label>`;}
function monthStrip(m){return `<div class="month-stats"><div><span>新增现金收入</span><strong>${amount(m.income)}</strong></div><div><span>家庭现金支出</span><strong>${amount(m.expense)}</strong></div><div><span>新增现金结余</span><strong class="blue-text">${amount(m.saving)}</strong></div><div><span>工资覆盖支出后结余</span><strong>${amount(m.salarySaving)}</strong></div></div>`;}
function ledgerView(){const m=C.monthInfo(state,month);return `<div class="toolbar">${monthPicker()}<div>${pill(m.reviewed?'已核对':m.complete?'待核对':'待补全',m.reviewed?'green':'amber')}${btn('月度汇总','summary','secondary','','')}${btn('导入 / 导出','nav','secondary','download','data-view="settings"')}</div></div>${m.mode==='summary'?`<div class="notice">本月使用汇总模式。逐笔记录会保留，但只有汇总金额参与统计。${btn('切换为逐笔','switch-detail','text')}</div>`:''}<section class="card">${monthStrip(m)}<div class="section-divider"></div><div class="card-heading"><h2>${m.mode==='summary'?'原有逐笔记录（未计入本月汇总）':'本月流水'}</h2><label class="search-box"><span class="sr-only">搜索备注或分类</span><input id="search" placeholder="搜索备注或分类" value="${esc(search)}"></label></div><div id="transactions">${transactionList()}</div></section><div class="note-line">${icon('check',16)} 转账、买股、既有股票变现和额外还本单独记录，不进入收入减支出。</div><div class="two-columns"><section class="card"><div class="card-heading"><h2>本月十项收支</h2>${btn('编辑 / 核对','summary','text','arrow')}</div>${categorySummary(m)}</section><section class="card soft-card"><h2>少记一步，也要记对</h2><div class="rule-list"><p><strong>工资只记到手现金</strong><span>公积金直接抵贷的部分，不再计入工资收入。</span></p><p><strong>买股与转账是资金去向</strong><span>偿还融资本金不重复算支出，也不额外增加储蓄。</span></p><p><strong>新增股权与旧股分开</strong><span>只记录本年新增、已归属且已变现的净回款。</span></p></div></section></div>`;}
function transactionList(){const list=state.transactions.filter(t=>t.date.startsWith(month)&&(!search||`${t.note} ${C.CATEGORIES.concat(C.TRANSFERS).find(c=>c.id===t.category)?.label}`.includes(search))).sort((a,b)=>b.date.localeCompare(a.date));return list.length?`<div class="table-scroll"><table><thead><tr><th>日期 / 事项</th><th>分类</th><th class="right">金额</th><th><span class="sr-only">操作</span></th></tr></thead><tbody>${list.map(t=>{const c=C.CATEGORIES.concat(C.TRANSFERS).find(c=>c.id===t.category);return `<tr><td><strong>${esc(t.note||c.label)}</strong><small>${t.date}${t.tripId?' · '+esc(state.trips.find(x=>x.id===t.tripId)?.name||'旅行'):''}</small></td><td>${pill(c.label,c.type==='income'?'green':c.type==='expense'?'':'purple')}</td><td class="right money ${c.type==='income'?'green-text':''}">${c.type==='income'?'+':c.type==='expense'?'−':''}${amount(t.amount)}</td><td class="row-actions"><button class="text-button" data-act="edit-tx" data-id="${esc(t.id)}">编辑</button><button class="text-button danger" data-act="delete-tx" data-id="${esc(t.id)}">删除</button></td></tr>`;}).join('')}</tbody></table></div>`:empty(search?'没有匹配的记录':'这个月，还没有流水','实际记录会保存在当前设备，断网也可以继续填写。',btn('记下第一笔','add-tx','secondary','plus'));}
function renderTransactions(){$('#transactions').innerHTML=transactionList();}
function categorySummary(m){return `<div class="category-grid">${C.CATEGORIES.map(c=>`<div><span>${c.short}</span><strong>${amount(m.amounts[c.id])}</strong></div>`).join('')}</div><p class="tiny muted">空白代表未知；填全十项或确认无发生项目后，才能完成核对。</p>`;}
function assetsView(){const s=latestSnapshot(),info=C.snapshotInfo(s);return `<div class="toolbar"><span class="muted">${s?'最新记录：'+s.date:'从期初账单或最近一期月结单开始'}</span>${btn('记录资产快照','snapshot','primary','plus')}</div><div class="stats-grid">${metric('已核实金融资产',info.financial,'现金 + 证券账户净权益，不含房产','assets','blue')}${metric('家庭净资产',info.net,'完整填写房产与所有负债后计算','home','purple')}${metric('证券融资余额（备查）',s?.verified?s.financing:null,'证券净权益中已扣除，不重复扣减','ledger','orange')}</div><section class="card"><div class="card-heading"><div><h2>资产快照历史</h2><p>股票涨跌与收支结余分别观察</p></div>${pill('人民币元')}</div>${state.snapshots.length?`<div class="table-scroll"><table><thead><tr><th>快照日期</th><th>金融资产</th><th>可用现金</th><th>家庭净资产</th><th>状态</th><th>操作</th></tr></thead><tbody>${[...state.snapshots].sort((a,b)=>b.date.localeCompare(a.date)).map(v=>{const n=C.snapshotInfo(v);return `<tr><td><strong>${v.date}</strong><small>${esc(v.note||'资产余额快照')}</small></td><td>${amount(n.financial)}</td><td>${amount(n.reserve)}</td><td>${amount(n.net)}</td><td>${pill(v.verified&&v.netConfirmed?'已核实':'待核实',v.verified&&v.netConfirmed?'green':'amber')}</td><td class="row-actions"><button class="text-button" data-act="snapshot" data-id="${esc(v.id)}">查看 / 编辑</button><button class="text-button danger" data-act="delete-snapshot" data-id="${esc(v.id)}">删除</button></td></tr>`;}).join('')}</tbody></table></div><div class="history-chart">${assetHistory()}</div>`:empty('还没有已记录的资产余额','当前估计不会自动成为期初资产。请按账单填写，并确认证券是否已扣除融资。',btn('填写第一份快照','snapshot','secondary','plus'))}</section><div class="two-columns"><section class="card reference-card"><div class="card-heading"><h2>待核验的参考信息</h2>${pill('未经核验','amber')}</div><div class="reference-note">${privateReferences()}</div></section><section class="card"><h2>始终使用同一口径</h2><div class="rule-list"><p><strong>证券填写账户净权益</strong><span>包含证券账户内现金，已扣融资。该现金不要再填入银行现金。</span></p><p><strong>负债只扣一次</strong><span>房贷与其他非证券负债在家庭净资产中扣除；证券融资仅备查。</span></p><p><strong>资产变动不等于投资收益</strong><span>入金、出金、股权归属和汇率都会影响余额。收益请单独抄月结单。</span></p></div></section></div>`;}
function assetHistory(){const list=[...state.snapshots].filter(v=>C.snapshotInfo(v).financial!==null).sort((a,b)=>a.date.localeCompare(b.date));if(list.length<2)return '<p class="tiny muted">至少两份已核实快照后显示历史变化；尚未核实的点不会连线。</p>';const vs=list.map(v=>C.snapshotInfo(v).financial),min=Math.min(0,...vs),max=Math.max(...vs,1),x=i=>45+i*660/(vs.length-1),y=v=>145-(v-min)/(max-min)*110;return `<svg viewBox="0 0 750 190" role="img" aria-label="已核实金融资产历史"><path d="${vs.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ')}" stroke="var(--blue)" stroke-width="2.5" fill="none"/>${vs.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="var(--blue)"/><text x="${x(i)}" y="${y(v)-12}" text-anchor="middle">${amount(v)}</text><text x="${x(i)}" y="175" text-anchor="middle">${list[i].date}</text>`).join('')}</svg>`;}
function budgetView(){const b=C.budgetFor(state,year),t=C.budgetTotals(b),a=C.annualInfo(state,year);return `<div class="toolbar"><span class="muted">${year} 年预算 · 计划与实际分别记录</span>${btn('调整预算与目标','budget-edit','primary','','')}</div><div class="stats-grid">${metric('全年工资预算',t.income,'夫妻税后现金工资，不含公积金','wallet','blue')}${metric('全年现金支出预算',t.expense,'包含房贷自付、生活及年度专项','ledger','orange')}${metric('预计工资结余',t.saving,`与年度目标相差 ${amount(t.saving-b.annual)}`,'flag','green')}</div><div class="two-columns"><section class="card"><div class="card-heading"><h2>年度支出安排</h2>${pill('预算')}</div>${[['房贷自付',Math.max(0,b.mortgage-b.fund)*12,'blue'],['日常生活',b.living*12,'teal'],['旅行',b.travel,'purple'],['车辆',b.car,'orange'],['教育、保险等及融资利息',b.other,'green']].map(([label,v,tone])=>`<div class="budget-row"><div><span>${label}</span><strong>${amount(v)}</strong></div>${progress(v,t.expense,tone)}</div>`).join('')}<p class="tiny muted">房贷月供 ${amount(b.mortgage)} − 公积金 ${amount(b.fund)} = 现金自付 ${amount(Math.max(0,b.mortgage-b.fund))} / 月。</p></section><section class="card"><h2>把目标落在每个月</h2><div class="goal-row"><span>固定储蓄<strong>${amount(b.fixed)}<small> / 月</small></strong></span>${pill('基础安排','blue')}</div><div class="goal-row"><span>争取储蓄<strong>${amount(b.stretch)}<small> / 月</small></strong></span>${pill('追加积累','purple')}</div><div class="goal-row"><span>工资全年目标<strong>${amount(b.annual)}</strong></span></div><div class="goal-row"><span>综合积累争取<strong>${amount(b.combined)}</strong></span></div><div class="reference-note">${esc(state.references?.bonus||'奖金与股权以实际净到账为准。未归属或未变现的股权不记现金收入。')}</div></section></div><section class="card"><div class="card-heading"><h2>12 个月的进度</h2><p>点击月份进入复盘</p></div><div class="months-grid">${a.months.map((m,i)=>`<button data-act="review-month" data-month="${year}-${String(i+1).padStart(2,'0')}" class="month-tile"><span>${i+1} 月 ${m.reviewed?icon('check',14):''}</span><strong>${amount(m.reviewed?m.salarySaving:null)}</strong><small>${m.reviewed?'已核对':m.complete?'待核对':'尚未完成'}</small></button>`).join('')}</div></section>`;}
function travelView(){const b=C.budgetFor(state,year),a=C.annualInfo(state,year),trips=state.trips.filter(t=>+t.year===year),planned=C.sum(trips.map(t=>t.budget));return `<div class="travel-banner"><div><p class="eyebrow">MAKE ROOM FOR MEMORIES</p><h2>去看看，生活的另一面。</h2><p>为期待留一份预算，让出发更从容。</p></div><div class="travel-art">${icon('travel',94)}</div></div><div class="stats-grid">${metric('全年旅行预算',b.travel,'转入旅行账户不算已经消费','travel','blue')}${metric('已记录旅行支出',a.travel,'含待核对月份；按当前收支模式汇总','ledger','purple')}${metric('旅行预算剩余',b.travel-a.travel,`旅行计划已分配 ${amount(planned)}；未扣作实际支出`,'wallet','green')}</div><section class="card"><div class="card-heading"><div><h2>下一段美好</h2><p>计划预算与实际付款分别记录</p></div>${btn('添加旅行计划','trip','secondary','plus')}</div>${trips.length?`<div class="trip-grid">${trips.map(t=>{const spent=C.sum(state.transactions.filter(x=>x.tripId===t.id&&x.category==='travel'&&x.date.startsWith(String(year))&&C.monthInfo(state,x.date.slice(0,7)).mode==='detail').map(x=>x.amount));return `<article class="trip-card"><span class="trip-icon">${icon('travel',27)}</span><h3>${esc(t.name)}</h3><p>${esc(t.note||'留一点期待给未来')}</p><div><span>计划 ${amount(t.budget)}</span><strong>已付 ${amount(spent)}</strong></div>${progress(spent,t.budget)}<p class="tiny muted">已付仅统计本年逐笔模式中关联的旅行流水</p><div class="trip-actions">${btn('记录付款','trip-pay','text','plus',`data-id="${esc(t.id)}"`)}${btn('编辑','trip','text','',`data-id="${esc(t.id)}"`)}${btn('删除','delete-trip','text danger','',`data-id="${esc(t.id)}"`)}</div></article>`;}).join('')}</div>`:empty('下一次出发，从这里开始','先记一份计划预算；付款时关联旅行，自动汇总实际支出。',btn('添加第一个旅行计划','trip','secondary','plus'))}${planned>b.travel?'<p class="form-error">计划预算合计已超过全年旅行预算，请调整计划或年度预算。</p>':''}</section><div class="note-line">${icon('check',16)} 原 Excel 里的旅行汇总进入全年支出，但不会被编造成某次旅行的付款。</div>`;}
function reviewView(){const m=C.monthInfo(state,month),s=state.snapshots.find(x=>x.date===C.monthEnd(month)),b=C.budgetFor(state,year);return `<div class="toolbar">${monthPicker()}${pill(m.reviewed?'本月已核对':'本月待完成',m.reviewed?'green':'amber')}</div><section class="card">${monthStrip(m)}</section><div class="review-layout"><section class="card"><div class="step-heading"><span>01</span><div><h2>让收支完整</h2><p>十项填全，无发生明确记 0</p></div>${pill(m.complete?'已补全':'待补全',m.complete?'green':'amber')}</div>${categorySummary(m)}<div class="card-actions">${btn('填写 / 核对收支','summary','secondary','ledger')}</div></section><section class="card"><div class="step-heading"><span>02</span><div><h2>留下月末快照</h2><p>${C.monthEnd(month)} · 同日账单</p></div>${pill(s?.verified&&s?.netConfirmed?'已核实':'待核实',s?.verified&&s?.netConfirmed?'green':'amber')}</div><p class="muted">更新现金、证券净权益和融资余额。缺失余额留空，不用估计代替已核实数字。</p><div class="review-balance"><span>可用现金储备<strong>${amount(C.snapshotInfo(s).reserve)}</strong></span><span>本月工资目标<strong>${amount(b.stretch)}</strong></span></div>${btn(s?'查看月末快照':'填写月末快照','review-snapshot','secondary','plus')}</section><section class="card review-notes"><div class="step-heading"><span>03</span><div><h2>给下个月一句提醒</h2><p>记录变化，也留下一点方向</p></div></div><div class="note-preview"><span>本月主要事项</span><p>${esc(m.note||'还没有记录。可以写下集中支出、奖金到账或现金安排。')}</p></div><div class="note-preview"><span>下月行动</span><p>${esc(m.action||'一件具体、可执行的小事就好。')}</p></div>${btn('写下复盘与行动','review-notes','secondary','plus')}</section><section class="card review-finish"><span class="finish-icon">${icon('check',28)}</span><h2>${m.reviewed?'这一个月，心中有数':'核对完成，再纳入累计'}</h2><p>收支补全并确认后进入年度结余。资产快照单独核实，不会用来反推收入。</p>${btn(m.reviewed?'撤销本月核对':'确认收支已核对',m.reviewed?'unreview':'confirm-review',m.reviewed?'secondary':'primary','check')}<p class="tiny muted">修改当月流水或汇总会自动撤销原核对结果。</p></section></div><section class="card todo-card"><div class="card-heading"><h2>家庭待办</h2>${btn('添加待办','add-todo','text','plus')}</div>${todoList()}</section>`;}
function todoList(){return state.todos.length?`<div class="todos">${state.todos.map(t=>`<div class="todo ${t.done?'done':''}"><button class="todo-check" data-act="toggle-todo" data-id="${esc(t.id)}" aria-label="${t.done?'重新打开':'完成'} ${esc(t.text)}">${icon(t.done?'check':'circle',20)}</button><span>${esc(t.text)}${t.due?`<small>${t.due}${!t.done&&t.due<C.chinaToday()?' · 已逾期':''}</small>`:''}</span><button class="text-button danger" data-act="delete-todo" data-id="${esc(t.id)}">删除</button></div>`).join('')}</div>`:'<div class="empty compact"><p>没有额外待办。把需要记住的小事放在这里。</p></div>';}
function settingsView(){return `<div class="settings-grid"><section class="card"><div class="card-heading"><div><h2>数据属于你的家庭</h2><p>本机加密 · 设备间密文同步</p></div><span class="metric-icon green">${icon('lock')}</span></div><p class="muted">记录始终在设备端加密保存。连接家庭同步后，云端只保存加密版本文件，不接收家庭金额明文或解密密钥；没有银行或券商连接。</p><div class="setting-row"><span>本机加密<small>${Store.isEncrypted()?'已开启，解锁密码不会发送到服务器':'必须开启后才能使用'}</small></span>${Store.isEncrypted()?btn('立即锁定','lock','secondary','lock'):btn('开启密码保护','vault','secondary','lock')}</div>${syncPanel()}<div class="setting-row"><span>持久存储<small id="persistStatus">申请减少浏览器自动回收，仍需定期备份。</small></span>${btn('申请保留数据','persist','secondary')}</div><div class="notice subtle">清理网站数据、卸载浏览器或遗失设备可能丢失本机记录。建议每月复盘后导出一份加密备份。密码无法找回。</div></section><section class="card"><h2>导入与备份</h2><p class="muted">原始 Excel 只在本机读取；导入前先预览，冲突时整批停止。</p><div class="data-actions">${btn('导入 Excel / CSV / 备份','import','secondary','upload')}${btn('导出加密完整备份','backup','primary','lock')}${btn('导出 Excel','export-xlsx','secondary','download')}${btn('导出流水 CSV','export-csv','secondary','download')}</div><p class="tiny muted">Excel 是只读报告与完整备份；编辑可见报告后不能直接恢复。原版三工作表支持继续录入后导入；相同月记录会跳过，不同月记录冲突会停止。CSV 仅包含逐笔流水。两者均为明文，请仅保存在可信位置。原工作簿保持原样。</p><details><summary>CSV 模板与导入规则</summary><p class="tiny muted">必需列：日期、分类、金额；可选列：id、备注、旅行ID。日期为 YYYY-MM-DD，金额为人民币元。已有 id 不重复导入。无 id 时按行内容去重，相同内容的多笔交易请添加不同 id。</p>${btn('下载空白 CSV 模板','csv-template','text','download')}</details><div class="setting-row"><span>已有数据<small>${state.transactions.length} 笔流水 · ${state.snapshots.length} 份快照 · ${state.trips.length} 个旅行计划</small></span>${pill('v1 数据格式')}</div></section><section class="card"><h2>随时打开，随手记录</h2><div class="rule-list"><p><strong>iPhone</strong><span>用 Safari 打开网址 → 分享 → 添加到主屏幕。首次联网打开后，等待离线资源缓存完成。</span></p><p><strong>Mac</strong><span>可直接用浏览器，或在 Safari 中选择“添加到程序坞”。</span></p><p><strong>离线使用</strong><span id="offlineStatus">${navigator.serviceWorker?.controller?'离线资源已就绪，断网可录入。':'正在准备离线资源；首次缓存完成后可离线使用。'}</span></p></div><div class="data-actions">${btn('检查离线资源 / 更新','check-update','secondary','refresh')}${btn('打开旅行基金','nav','secondary','travel','data-view="travel"')}${btn('打开年度计划','nav','secondary','budget','data-view="budget"')}</div></section><section class="card"><h2>让工作台适合你</h2><div class="setting-row"><span>外观<small>浅色、深色或跟随设备</small></span><select id="themeSelect" aria-label="外观模式">${[['system','跟随系统'],['light','浅色'],['dark','深色']].map(([k,l])=>`<option value="${k}" ${state.preferences.theme===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting-row"><span>复盘提醒<small>每月 5 日 20:00 · Asia/Shanghai<br>独立自动提醒已设置，应用仅展示。</small></span>${pill('沿用已有提醒','blue')}</div><div class="setting-row"><span>新的记录年份<small>新增年度预算，保留所有历史记录</small></span>${btn('新增年份','add-year','secondary','plus')}</div><p class="tiny muted">这是财务首期版本。自动同步在工作台解锁、联网且处于前台时进行；后台暂停时，回到应用会继续。云端不代替你保留的加密备份。</p></section></div>`;}
function txDialog(id='',tripId=''){const old=state.transactions.find(t=>t.id===id),trip=state.trips.find(t=>t.id===tripId),v=old||{date:C.chinaToday(),category:trip?'travel':'living',amount:'',note:'',tripId:tripId||''};const categories=C.CATEGORIES.concat(C.TRANSFERS);showDialog(old?'编辑记录':'记下这一笔',`<div class="segmented-help">人民币元 · 实际发生后记录</div><div class="form-grid">${field('发生日期','date',v.date,'date',`required max="${C.chinaToday()}"`)}${moneyField('金额（元）','amount',v.amount)}<label class="field"><span>分类</span><select name="category">${categories.map(c=>`<option value="${c.id}" ${c.id===v.category?'selected':''}>${c.label}${!c.type?' · 不计收支':''}</option>`).join('')}</select></label><label class="field"><span>关联旅行（仅旅行支出）</span><select name="tripId"><option value="">不关联</option>${state.trips.map(t=>`<option value="${esc(t.id)}" ${t.id===v.tripId?'selected':''}>${t.year} · ${esc(t.name)}</option>`).join('')}</select></label></div>${field('备注','note',v.note,'text','maxlength="2000" placeholder="例如：本月工资、超市采购"')}<label class="checkbox"><input name="equityConfirm" type="checkbox" ${v.category==='equity'&&old?'checked':''}><span>若记为新增股权收入：确认本年新增、已归属、已变现，且净回款税费只扣一次。</span></label><div class="notice subtle">买股、转账、融资还本及旧股出售不记新增收入或消费。公积金直接抵贷部分不记工资。</div>`,'保存记录',async f=>{const t={id:old?.id||C.uid(),date:f.get('date'),category:f.get('category'),amount:Number(f.get('amount')),note:f.get('note'),tripId:f.get('category')==='travel'?f.get('tripId'):''};if(t.date>C.chinaToday())throw Error('未来收支请放入预算，流水只记录实际发生。');if(t.category==='equity'&&!f.get('equityConfirm'))throw Error('请确认新增股权的归属、年份与净变现口径。');if(t.tripId&&String(state.trips.find(x=>x.id===t.tripId).year)!==t.date.slice(0,4))throw Error('旅行计划年份与付款年份不一致。');await commit(s=>{if(old){s.transactions=s.transactions.filter(x=>x.id!==old.id);C.invalidate(s,old.date.slice(0,7));}C.addTransaction(s,t);},'记录已保存到本机');year=+t.date.slice(0,4);month=t.date.slice(0,7);render();});}
function summaryDialog(){const m=C.monthInfo(state,month);showDialog(`${month.replace('-',' 年 ')} 月收支核对`,`<p class="muted">选择本月唯一的统计来源。汇总和逐笔不会叠加；切换后原数据保留。</p><label class="field"><span>收支来源</span><select name="mode"><option value="detail" ${m.mode==='detail'?'selected':''}>逐笔记录自动汇总</option><option value="summary" ${m.mode==='summary'?'selected':''}>按月填写汇总（适合原 Excel）</option></select></label><div id="summaryInputs" class="form-grid">${C.CATEGORIES.map(c=>moneyField(c.label,c.id,state.months[month]?.amounts?.[c.id]??'',true)).join('')}</div><p id="detailHint" class="tiny muted">逐笔模式金额来自流水；下方确认仅把未发生的分类视为 0。</p><label class="checkbox"><input type="checkbox" name="zeroChecked" ${m.zeroChecked?'checked':''}><span>逐笔记录已经补齐，未出现的收支分类已确认没有发生（计为 0）。</span></label><label class="checkbox"><input type="checkbox" name="reviewed" ${m.reviewed?'checked':''}><span>十项金额与账单核对无误，纳入年度累计。</span></label><p class="tiny muted">汇总模式：十项都需填写，确认无发生填 0。切换统计来源会重新检查核对状态。</p>`,'保存本月收支',async f=>{const mode=f.get('mode'),amounts=Object.fromEntries(C.CATEGORIES.map(c=>[c.id,f.get(c.id)===''?null:Number(f.get(c.id))]));await commit(s=>{s.months[month]={...(s.months[month]||{}),mode,amounts,zeroChecked:!!f.get('zeroChecked'),reviewed:false};if(f.get('reviewed')){if(month>C.chinaToday().slice(0,7))throw Error('未来月份不能作为已核对实际收支。');const info=C.monthInfo(s,month);if(!info.complete)throw Error('还有未知收支。汇总模式填全十项；逐笔模式补齐流水并确认无发生分类。');s.months[month].reviewed=true;}},'本月收支已保存');},true);const select=modal.querySelector('[name="mode"]');const sync=()=>{const summary=select.value==='summary';$('#summaryInputs').hidden=!summary;$('#detailHint').hidden=summary;modal.querySelector('[name="zeroChecked"]').closest('label').hidden=summary;};select.onchange=sync;sync();}
function snapshotDialog(id='',date=''){const old=state.snapshots.find(s=>s.id===id),s=old||{date:date||C.chinaToday()};const nums=[['现金及存款（不含证券账户现金）','cash'],['其中已有明确用途的现金','reserved'],['美股账户净权益（已扣融资）','usNet',true],['其他独立投资净值（已扣相关融资）','otherNet',true],['证券融资余额（仅备查，不再扣）','financing'],['房产估值（未知留空）','property'],['房贷剩余本金（未知留空）','mortgageDebt'],['其他非证券负债（无则填 0）','otherDebt'],['投资净盈亏（选填，可为负）','pnl',true]];showDialog(old?'查看 / 编辑资产快照':'记录一份资产快照',`${field('余额日期','date',s.date,'date','required')}<p class="tiny muted">全部折算人民币元，采用同日账单。0 表示已确认没有，空白表示未知。证券账户内现金只含在净权益中。</p><div class="form-grid">${nums.map(([label,k,negative])=>moneyField(label,k,s[k],true,negative)).join('')}</div>${field('主要事项 / 口径备注','note',s.note,'text','maxlength="2000"')}${field('下月行动','action',s.action,'text','maxlength="2000"')}<label class="checkbox"><input type="checkbox" name="netConfirmed" ${s.netConfirmed?'checked':''}><span>确认证券填的是净权益、已扣融资、含账户现金，且各账户之间没有重复。</span></label><label class="checkbox"><input type="checkbox" name="verified" ${s.verified?'checked':''}><span>本次已填写的金额均已对照同日账单核实。</span></label><p class="tiny muted">现金、两项证券净值填全并勾选核实后计算金融资产。房产及非证券负债也填全后才显示家庭净资产。未来日期不能确认为实际余额。</p>`,'保存快照',async f=>{const v={id:old?.id||C.uid(),date:f.get('date'),note:f.get('note'),action:f.get('action'),verified:!!f.get('verified'),netConfirmed:!!f.get('netConfirmed')};for(const [,k] of nums)v[k]=f.get(k)===''?null:Number(f.get(k));if(v.reserved!==null&&(v.cash===null||v.reserved>v.cash))throw Error('已有用途现金不能超过现金余额；请先填写现金余额。');if(v.verified&&v.date>C.chinaToday())throw Error('未来日期不能确认为已核实资产，请在实际余额日填写。');await commit(s=>{if(s.snapshots.some(x=>x.date===v.date&&x.id!==v.id))throw Error('同一天已有快照，请编辑原快照。');s.snapshots=s.snapshots.filter(x=>x.id!==v.id);s.snapshots.push(v);},'资产快照已保存');},true);}
function budgetDialog(){const b=C.budgetFor(state,year);showDialog(`调整 ${year} 年预算`,`<p class="muted">这是计划金额，不会填入实际收支。各年份独立保存。</p><div class="form-grid">${C.BUDGET_FIELDS.map(([k,label])=>moneyField(label,k,b[k])).join('')}</div>`,'保存年度预算',async f=>{const b=Object.fromEntries(C.BUDGET_FIELDS.map(([k])=>[k,Number(f.get(k))]));if(b.fund>b.mortgage)throw Error('公积金抵扣不应超过房贷总供，请核对预算。');if(b.stretch<b.fixed)throw Error('争取储蓄目标应不低于固定目标。');await commit(s=>{s.budgets[year]=b;},'年度预算已保存');},true);}
function tripDialog(id=''){const t=state.trips.find(t=>t.id===id)||{name:'',budget:'',note:'',year};showDialog(id?'编辑旅行计划':'下一段旅行',`${field('旅行名称','name',t.name,'text','required maxlength="80" placeholder="例如：暑期家庭旅行"')}${moneyField('计划预算（元）','budget',t.budget)}${field('计划年份','year',t.year,'number','required min="2000" max="2100"')}${field('备注','note',t.note,'text','maxlength="500" placeholder="想去的地方、时间或准备事项"')}<p class="tiny muted">计划本身不算支出。实际付款时使用“旅行”分类，并关联本计划。</p>`,'保存计划',async f=>{const v={id:id||C.uid(),name:f.get('name').trim(),budget:Number(f.get('budget')),note:f.get('note'),year:+f.get('year')};if(!v.name)throw Error('请填写旅行名称。');if(id&&v.year!==t.year&&state.transactions.some(x=>x.tripId===id))throw Error('已有付款关联，不能更改计划年份。');await commit(s=>{s.trips=s.trips.filter(x=>x.id!==v.id);s.trips.push(v);},'旅行计划已保存');});}
function notesDialog(){const m=C.monthInfo(state,month);showDialog('留给下个月的自己',`<label class="field"><span>本月主要事项</span><textarea name="note" rows="4" maxlength="2000" placeholder="这个月，有什么值得记下？">${esc(m.note||'')}</textarea></label><label class="field"><span>下月行动</span><textarea name="action" rows="3" maxlength="2000" placeholder="具体的一件小事">${esc(m.action||'')}</textarea></label><p class="tiny muted">当期结余去向（选填，仅作分配记录，不再次计算收入、支出或储蓄）</p><div class="form-grid">${[['转入储蓄账户','savings'],['用于融资还本','repay'],['用于新增投资','invest'],['用于额外还房贷','mortgage']].map(([label,k])=>moneyField(label,k,m.allocations?.[k],true)).join('')}</div>`,'保存复盘',async f=>{await commit(s=>{s.months[month]={...(s.months[month]||{}),note:f.get('note'),action:f.get('action'),allocations:Object.fromEntries(['savings','repay','invest','mortgage'].map(k=>[k,f.get(k)===''?null:Number(f.get(k))]))};},'复盘已保存');});}
function confirmDialog(title,text,action){showDialog(title,`<p>${esc(text)}</p>`,'确认',action);}
function download(text,name,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function fileImport(){const input=document.createElement('input');input.type='file';input.accept='.xlsx,.csv,.json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>20*1024*1024){notify('文件超过 20MB，请拆分后导入。',true);return;}try{const ext=file.name.split('.').pop().toLowerCase();if(ext==='xlsx'){const p=readWorkbook(await file.arrayBuffer());previewImport(p,file.name);}else if(ext==='csv'){const tx=await C.csvTransactions(await file.text());const p=C.applyCSV(state,tx);previewImport({kind:'csv',...p,description:`新增 ${p.added} 笔流水，跳过 ${p.duplicates} 笔重复记录；相关月份会重新核对`},file.name);}else if(ext==='json'){const raw=JSON.parse(await file.text());if(raw.format==='family-hub-encrypted-v1'){showDialog('解锁加密备份',`${field('备份密码','password','','password','required autocomplete="current-password"')}<p class="tiny muted">在本机解密，不上传密码或文件。解密后先预览，再选择是否恢复。</p>`,'解密并预览',async f=>{const {data}=await Store.decrypt(raw,f.get('password'));modal.close();setTimeout(()=>previewImport({kind:'backup',state:data,description:'加密完整备份（包含所有年份）'},file.name),0);});}else previewImport({kind:'backup',state:C.validateState(raw),description:'明文完整备份（包含所有年份）'},file.name);}else throw Error('请选择 .xlsx、.csv 或 .json 文件。');}catch(e){notify(e.message,true);}};input.click();}
function previewImport(p,name){let candidate=p.kind==='csv'?p.candidate:p.kind==='legacy'?applyLegacy(state,p):stripSyncSecrets(p.state);C.validateState(candidate);const replace=p.kind==='backup';pendingImport=p;showDialog('导入前，再看一眼',`<div class="import-file">${icon('upload',27)}<strong>${esc(name)}</strong></div><p>${esc(p.description)}</p>${p.kind==='legacy'?`<p class="tiny muted">本次新增 ${Object.keys(candidate.months).length-Object.keys(state.months).length} 个月、${candidate.snapshots.length-state.snapshots.length} 份快照；相同记录跳过。</p>`:''}${p.kind==='legacy'?'<p class="tiny muted">原始表格中的资产带入为“待核实”；不会将参考估计带入期初资产。导入会更新该年度预算。</p>':''}<div class="notice ${replace?'warning':''}">${replace?'恢复将替换当前设备的全部记录。已连接同步时，这些变更也会同步到其他设备；请先导出当前数据备份。':'新增数据会在确认后一次性写入；冲突不会覆盖原记录。'}</div><label class="checkbox"><input name="confirm" type="checkbox" required><span>${replace?'我已备份需要保留的现有数据，同意替换本机全部记录。':'我已核对导入范围和预算变化。'}</span></label>`,'确认导入',async()=>{await commit(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,structuredClone(candidate));},'数据已导入本机');pendingImport=null;});}
async function backupDialog(){showDialog('给记录一份安全的备份',`${field('备份密码（至少 10 位）','password','','password','required minlength="10" autocomplete="new-password"')}${field('再次输入密码','repeat','','password','required minlength="10" autocomplete="new-password"')}<p class="tiny muted">完整备份含全部年份、待办和计划。使用 AES-GCM 加密。请将密码另行保管，无法找回；这不改变本机锁定密码。</p>`,'导出加密备份',async f=>{if(f.get('password')!==f.get('repeat'))throw Error('两次密码不一致。');download(JSON.stringify(await Store.encrypt(stripSyncSecrets(state),f.get('password'))),`家庭工作台-加密备份-${C.chinaToday()}.json`);notify('加密备份已生成，请确认浏览器下载完成');});}
async function vaultDialog(){showDialog('开启本机密码保护',`${field('解锁密码（至少 10 位）','password','','password','required minlength="10" autocomplete="new-password"')}${field('再次输入','repeat','','password','required minlength="10" autocomplete="new-password"')}<div class="notice">密码只用于本机加密，无法找回。工作台隐藏超过一分钟会锁定。开启前建议导出备份。</div>`,'加密本机数据',async f=>{if(f.get('password')!==f.get('repeat'))throw Error('两次密码不一致。');busy=true;try{await Store.enableVault(state,f.get('password'));render();notify('本机加密已开启');}finally{busy=false;}});}
function lockScreen(){sync.stop();if(modal.open)modal.close();state=null;Store.lock();app.innerHTML=`<div class="lock-screen"><div class="appmark">${icon('home',32)}</div><p class="eyebrow">FAMILY HUB</p><h1>欢迎回家。</h1><p>输入密码，打开你的家庭空间。</p><form id="unlockForm">${field('本机解锁密码','password','','password','required autocomplete="current-password"')}<p class="form-error" id="unlockError" role="alert"></p><button class="button primary" type="submit">${icon('lock',16)}解锁工作台</button></form><p class="tiny muted">密码无法找回。本机数据保持加密；已配对设备可同步云端密文。<br>关闭页面后可重新尝试；不会自动清空记录。</p></div>`;$('#unlockForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{state=await Store.unlock(new FormData(e.currentTarget).get('password'));render();sync.start();}catch(err){$('#unlockError').textContent=err.message;b.disabled=false;}};}

function privateReferences(){const r=state.references;if(!r)return '未预置家庭资产估计。请根据自己的账单核实并录入，空白表示未知。';return `${pill('未经核验','amber')} ${esc(r.asOf||'')} 参考估计：现金 ${amount(r.cash)} · 美股 ${amount(r.usNet)} · 其他股票 ${amount(r.otherNet)}。仅供核对，不计入资产合计。`;}
function enrollmentScreen(candidate){
 app.innerHTML=`<div class="lock-screen"><div class="appmark">${icon('home',32)}</div><p class="eyebrow">FAMILY HUB / PRIVATE BY DESIGN</p><h1>为家庭，留一处私密空间。</h1><p>先设置此设备的解锁密码，再导入家庭数据。<br>网址只提供应用，任何访客都看不到你的财务记录。</p><form id="enrollForm">${field('解锁密码（至少 10 位）','password','','password','required minlength="10" autocomplete="new-password"')}${field('再次输入密码','repeat','','password','required minlength="10" autocomplete="new-password"')}<p class="form-error" id="enrollError" role="alert"></p><button class="button primary" type="submit">${icon('lock',16)}创建加密空间</button></form><p class="tiny muted">密码无法找回。请妥善保管，并定期导出加密备份。<br>创建空间后，在“数据与设置”连接家庭同步。两台设备使用同一个私密配对码。</p></div>`;
 $('#enrollForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=e.submitter;b.disabled=true;try{if(f.get('password')!==f.get('repeat'))throw Error('两次密码不一致。');await Store.enableVault(candidate,f.get('password'));state=candidate;render();sync.start();notify('加密空间已创建。请导入自己的 Excel 或初始化文件。');}catch(err){$('#enrollError').textContent=err.message;b.disabled=false;}};
}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,id=el.dataset.id;try{if(act==='close'){e.preventDefault();modal.close();return;}if(act==='reload'){location.reload();return;}if(!state)return;if(act==='nav'){e.preventDefault();navigate(el.dataset.view);return;}if(act==='add-tx'||act==='edit-tx')txDialog(id);else if(act==='summary')summaryDialog();else if(act==='switch-detail')confirmDialog('切换为逐笔模式','本月汇总金额会保留，但不再参与统计。原核对结果撤销，以逐笔记录重新核对。',()=>commit(s=>{s.months[month]={...(s.months[month]||{}),mode:'detail',reviewed:false,zeroChecked:false};},'已切换逐笔模式'));else if(act==='snapshot')snapshotDialog(id);else if(act==='review-snapshot')snapshotDialog(state.snapshots.find(x=>x.date===C.monthEnd(month))?.id,C.monthEnd(month));else if(act==='budget-edit')budgetDialog();else if(act==='trip')tripDialog(id);else if(act==='trip-pay')txDialog('',id);else if(act==='review-notes')notesDialog();else if(act==='review-month'){month=el.dataset.month;year=+month.slice(0,4);navigate('review');}else if(act==='confirm-review'){if(month>C.chinaToday().slice(0,7))throw Error('未来月份不能核对为实际收支，请先选择已发生月份。');const m=C.monthInfo(state,month);if(!m.complete){summaryDialog();return;}confirmDialog('确认本月收支','十项收支核对无误，确认后纳入全年累计。',()=>commit(s=>{s.months[month]={...(s.months[month]||{}),reviewed:true};},'本月已纳入年度累计'));}else if(act==='unreview')confirmDialog('撤销本月核对','记录保留，本月暂不进入年度累计。',()=>commit(s=>{s.months[month].reviewed=false;},'已撤销核对'));else if(act==='hide'){hidden=!hidden;render();}else if(act==='theme'){await commit(s=>s.preferences.theme=(document.documentElement.dataset.theme==='dark'?'light':'dark'));}else if(act==='add-todo')showDialog('记下一件小事',`${field('待办事项','text','','text','required maxlength="200"')}${field('截止日期（可选）','due','','date')}`,'添加待办',async f=>{if(!f.get('text').trim())throw Error('请填写待办事项。');await commit(s=>s.todos.push({id:C.uid(),text:f.get('text').trim(),due:f.get('due'),done:false}),'待办已添加');});else if(act==='toggle-todo')await commit(s=>{const t=s.todos.find(t=>t.id===id);t.done=!t.done;});else if(act.startsWith('delete-')){const type=act.slice(7),config={tx:['删除这笔记录？','删除后相关月份将重新核对。','transactions'],snapshot:['删除这份快照？','此日期的资产记录将从本机移除。','snapshots'],todo:['删除这条待办？','该待办将从本机移除。','todos'],trip:['删除旅行计划？','已关联付款会保留为旅行支出，仅解除计划关联。','trips']}[type];if(config)confirmDialog(config[0],config[1],()=>commit(s=>{if(type==='tx')C.invalidate(s,s.transactions.find(t=>t.id===id).date.slice(0,7));if(type==='trip')s.transactions.filter(t=>t.tripId===id).forEach(t=>t.tripId='');s[config[2]]=s[config[2]].filter(t=>t.id!==id);},'已删除'));}else if(act==='sync-connect')syncConnectDialog();else if(act==='sync-now'){sync.schedule(0);notify('正在检查设备间更新');}else if(act==='sync-pair')syncPairDialog();else if(act==='sync-copy'){await navigator.clipboard.writeText(sync.code());notify('配对码已复制，请仅粘贴到自己的另一台设备');}else if(act==='sync-conflicts')syncConflictDialog();else if(act==='sync-disconnect')confirmDialog('退出此设备的同步','本机记录仍保留；其他设备和云端记录不会删除。',async()=>{await commit(s=>{delete s.syncLink;},'此设备已退出同步',{disconnect:true});sync.stop();sync.setStatus('off','未连接同步');render();});else if(act==='import')await fileImport();else if(act==='backup')await backupDialog();else if(act==='vault')await vaultDialog();else if(act==='lock')lockScreen();else if(act==='export-xlsx')confirmDialog('导出明文 Excel','包含所有年份的完整备份页。请保存在可信位置，避免分享到公共空间。',async()=>{exportWorkbook(state,year);notify('Excel 已生成，请确认下载完成');});else if(act==='export-csv')confirmDialog('导出明文流水 CSV','CSV 只包含逐笔记录，不含月度汇总、预算与快照。完整迁移请使用加密备份或 Excel。',async()=>download(C.transactionsCSV(state),`家庭流水-${C.chinaToday()}.csv`,'text/csv;charset=utf-8'));else if(act==='csv-template')download(C.csvString([['id','日期','分类','金额','备注','旅行ID']]),'家庭工作台-流水导入模板.csv','text/csv;charset=utf-8');else if(act==='persist'){const granted=await navigator.storage?.persist?.();$('#persistStatus').textContent=granted?'浏览器已允许持久存储；仍建议每月备份。':'浏览器暂未授予持久存储；请定期导出备份。';notify(granted?'已获得持久存储许可':'暂未获许可，请定期备份');}else if(act==='add-year')showDialog('新的一年，继续记录',field('记录年份','year',year+1,'number','required min="2000" max="2100"'),'创建年度预算',async f=>{const y=+f.get('year');if(state.budgets[y])throw Error('该年度预算已存在。');await commit(s=>s.budgets[y]={...C.DEFAULT_BUDGET},'新年度已创建');year=y;month=`${y}-01`;render();});else if(act==='check-update'){if(!swRegistration)throw Error('离线缓存未就绪，请通过 HTTPS 或 localhost 打开。');await swRegistration.update();if(swRegistration.waiting){confirmDialog('应用有新版本','请先保存当前填写内容。更新页面不会清空本机记录。',async()=>{swRegistration.waiting.postMessage('ACTIVATE_UPDATE');navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});});}else notify(navigator.serviceWorker.controller?'离线资源已就绪，当前为最新版本':'资源准备中，请稍后重新打开');}}catch(err){notify(err.message,true);}});
document.addEventListener('change',async e=>{if(e.target.id==='themeSelect')try{await commit(s=>s.preferences.theme=e.target.value);}catch(err){notify(err.message,true);}});
window.addEventListener('online',()=>{if(state){render();sync.schedule(0);}});window.addEventListener('offline',()=>{if(state){render();if(state.syncLink)sync.setStatus('pending','离线 · 已保存本机，联网后继续同步');}});
let hiddenAt=null,lockTimer;document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();if(state&&Store.isEncrypted())lockTimer=setTimeout(()=>{if(!busy)lockScreen();},60000);}else{clearTimeout(lockTimer);if(hiddenAt&&Date.now()-hiddenAt>=60000&&state&&Store.isEncrypted()&&!busy)lockScreen();hiddenAt=null;if(state)sync.schedule(0);}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(titles[v]&&v!==view){view=v;render();}});
try{const routeBeforeUnlock=location.hash.slice(1);if(titles[routeBeforeUnlock])view=routeBeforeUnlock;const loaded=await Store.openStore();if(loaded.locked)lockScreen();else{state=loaded.data;const route=location.hash.slice(1);if(titles[route])view=route;if(!Store.isEncrypted()){enrollmentScreen(state);state=null;}else{render();sync.start();}}if('serviceWorker'in navigator){swRegistration=await navigator.serviceWorker.register('./sw.js');swRegistration.update().catch(()=>{});}}catch(e){app.innerHTML=`<div class="lock-screen"><h1>暂时无法打开本机数据</h1><p>${esc(e.message)}</p><p>请使用普通浏览模式和 HTTPS / localhost；不要清理网站数据，以免丢失已有记录。</p><button class="button secondary" data-act="reload">重新载入</button></div>`;}
